function introComplete(text){solved=true;hintMark=null;finished.add(current().id);controls();updateProgress();drawIntro();$('instruction').textContent='';say(text,'correct')}
function introPick(key){if(solved)return;const q=current();if(q.kind==='choice'){const i=Number(key);if(i===q.answer)introComplete(q.feedback[i]);else incorrect(q.feedback[i]);return}const l=layouts(q).start,m=q.moves[q.focusMove];let ok;if(q.kind==='source'){const s=l.sources.find(s=>s.id===key);ok=s?.key===locKey(m.from)}else ok=key===targetForMove(q,m);if(ok){if(q.kind==='source')selected=l.sources.find(s=>s.id===key);introComplete(q.kind==='source'?'You identified the electron pair that supplies this change.':'You identified where this electron pair goes in the displayed change.');}else{const atom=key.startsWith('atom:');incorrect((q.kind==='source'&&atom?'Start at electrons—a lone pair or a bond—not at an atom label. ':q.kind==='target'&&m.to.type==='lp'?'This pair becomes a lone pair, so choose the receiving atom. ':q.kind==='target'&&targetForMove(q,m).startsWith('bond:')?'This pair increases a bond order, so choose the receiving bond. ':'That is not the electron source or destination for the change in this question. ')+q.hint)}}
function introHint(){say(current().hint);if(current().kind==='choice')return;const q=current(),l=layouts(q).start,m=q.moves[q.focusMove];hintLevel++;if(hintLevel>=2){hintMark=q.kind==='source'?l.sources.filter(s=>s.key===locKey(m.from)):[l.targets.find(t=>t.key===targetForMove(q,m))];drawIntro()}}
function drawIntro(){const q=current();$('intro-options').hidden=q.kind!=='choice';$('reaction-grid').hidden=q.kind==='choice';$('keyboard-help').hidden=true;if(q.kind==='choice'){$('intro-options').innerHTML=q.options.map((o,i)=>`<button data-option="${i}" ${solved?'disabled':''}>${esc(o)}</button>`).join('');return}const ls=layouts(q),l=ls.start,v=ls.view,view=`${v.x} ${v.y} ${v.w} ${v.h}`,m=q.moves[q.focusMove];let html=defs()+molecule(l,q);if(solved){const source=selected||l.sources.find(s=>s.key===locKey(m.from)),target=l.targets.find(t=>t.key===targetForMove(q,m));html+='<g class="answer-arrow">'+arrowPath(ls.routes.get(source.id+'>'+target.key)||routeArrow(l,source,target))+'</g>';}else{if(q.kind==='target'){const s=l.sources.find(s=>s.key===locKey(m.from));html+=`<circle class="intro-origin" cx="${s.x}" cy="${s.y}" r="12"/>`;}const choices=q.kind==='source'?[...l.targets.filter(t=>t.atom).map(t=>({...t,choice:t.key})),...l.sources.map(s=>({...s,choice:s.id}))]:l.targets.map(t=>({...t,choice:t.key}));html+=choices.map(t=>`<circle class="hit intro-hit" data-pick="${esc(t.choice)}" cx="${t.x}" cy="${t.y}" r="${q.kind==='source'?13:17}" tabindex="0" role="button" aria-label="${esc(t.label)}"/>`).join('');if(hintMark)for(const p of hintMark)html+=`<circle class="hint-ring" cx="${p.x}" cy="${p.y}" r="18"/>`;}
mountReaction(html,ls,q);const b=$('board');b.addEventListener('click',e=>{if(e.target.dataset.pick)introPick(e.target.dataset.pick)});b.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset.pick){e.preventDefault();introPick(e.target.dataset.pick)}})}

